//! LPRF Parser - Parser library for .lprf line profiler files
//!
//! This crate provides functionality to parse and analyze .lprf binary profile files
//! generated by the line-profiler runtime.

use anyhow::{Context, Result, bail};
use std::collections::HashMap;
use std::fs::File;
use std::io::Read as IoRead;
use std::net::TcpStream;
use std::path::Path;

/// File format magic bytes
const MAGIC: &[u8; 4] = b"LPRF";

// ============================================================================
// Public API: Tree data structures
// ============================================================================

/// Type of node in the profile tree
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TreeNodeType {
    Function,
    Line,
}

/// A node in the profile tree
#[derive(Debug, Clone)]
pub struct TreeNode {
    pub node_type: TreeNodeType,
    pub name: String,
    pub line: u32,
    pub inclusive_time_ns: u64,
    pub exclusive_time_ns: u64,
    pub call_count: u64,
    pub is_library: bool,
    pub children: Vec<TreeNode>,
}

impl TreeNode {
    /// Calculate inclusive percentage relative to total time
    pub fn inclusive_percent(&self, total_time_ns: u64) -> f64 {
        if total_time_ns > 0 {
            (self.inclusive_time_ns as f64 / total_time_ns as f64) * 100.0
        } else {
            0.0
        }
    }

    /// Calculate exclusive percentage relative to total time
    pub fn exclusive_percent(&self, total_time_ns: u64) -> f64 {
        if total_time_ns > 0 {
            (self.exclusive_time_ns as f64 / total_time_ns as f64) * 100.0
        } else {
            0.0
        }
    }
}

/// The complete profile tree with metadata
#[derive(Debug)]
pub struct ProfileTree {
    total_time_ns: u64,
    pub timestamp_ns: u64,
    pub version: u32,
    pub roots: Vec<TreeNode>,
}

impl ProfileTree {
    /// Get the total elapsed time in nanoseconds
    pub fn get_total_time(&self) -> u64 {
        self.total_time_ns
    }
}

// ============================================================================
// Symbol Map
// ============================================================================

/// Symbol mapping from IDs to names
#[derive(Debug, Default, Clone)]
pub struct SymbolMap {
    functions: HashMap<u64, String>,
    /// Location ID -> (file, line, column, is_user_code)
    locations: HashMap<u64, (String, u32, u32, bool)>,
}

impl SymbolMap {
    /// Create a new empty symbol map
    pub fn new() -> Self {
        Self::default()
    }

    /// Load symbol map from a .profiler-map file
    pub fn from_file<P: AsRef<Path>>(path: P) -> Result<Self> {
        use std::io::{BufRead, BufReader};
        let file = File::open(path.as_ref()).context("Failed to open symbol map file")?;
        let reader = BufReader::new(file);
        let mut map = SymbolMap::default();

        for line in reader.lines() {
            let line = line?;
            let parts: Vec<&str> = line.splitn(3, ' ').collect();
            if parts.len() < 3 {
                continue;
            }

            match parts[0] {
                "F" => {
                    if let Ok(id) = parts[1].parse::<u64>() {
                        let name = demangle_name(parts[2]);
                        map.functions.insert(id, name);
                    }
                }
                "L" => {
                    if let Ok(id) = parts[1].parse::<u64>() {
                        if let Some((file, line, col, is_user)) = parse_location(parts[2]) {
                            map.locations.insert(id, (file, line, col, is_user));
                        }
                    }
                }
                _ => {}
            }
        }

        Ok(map)
    }

    /// Get function name by ID
    pub fn get_function(&self, id: u64) -> Option<&str> {
        self.functions.get(&id).map(|s| s.as_str())
    }

    /// Get location info by ID
    pub fn get_location(&self, id: u64) -> Option<&(String, u32, u32, bool)> {
        self.locations.get(&id)
    }

    /// Insert a function mapping
    pub fn insert_function(&mut self, id: u64, name: String) {
        self.functions.insert(id, name);
    }

    /// Insert a location mapping
    pub fn insert_location(&mut self, id: u64, file: String, line: u32, col: u32, is_user: bool) {
        self.locations.insert(id, (file, line, col, is_user));
    }
}

// ============================================================================
// Profile Data Structures
// ============================================================================

/// Profile file header
#[derive(Debug, Clone)]
pub struct ProfileHeader {
    pub version: u32,
    pub timestamp: u64,
    pub elapsed_ns: u64,
    node_count: u32,
}

impl ProfileHeader {
    /// Get the number of nodes in the profile
    pub fn node_count(&self) -> u32 {
        self.node_count
    }
}

/// A node in the profile data
#[derive(Debug, Clone)]
pub struct ProfileNode {
    node_type: u8,
    func_id: u64,
    line: u32,
    column: u32,
    call_count: u64,
    self_time_ns: u64,
    total_time_ns: u64,
    depth: u16,
    parent_func_id: u64,
}

impl ProfileNode {
    /// Check if this is a function node (vs a line node)
    pub fn is_function(&self) -> bool {
        self.node_type == 1
    }

    /// Get the function ID
    pub fn func_id(&self) -> u64 {
        self.func_id
    }

    /// Get the line number
    pub fn line(&self) -> u32 {
        self.line
    }

    /// Get the column number
    pub fn column(&self) -> u32 {
        self.column
    }

    /// Get the call count
    pub fn call_count(&self) -> u64 {
        self.call_count
    }

    /// Get self time in nanoseconds
    pub fn self_time_ns(&self) -> u64 {
        self.self_time_ns
    }

    /// Get total time in nanoseconds
    pub fn total_time_ns(&self) -> u64 {
        self.total_time_ns
    }

    /// Get the depth in the call tree
    pub fn depth(&self) -> u16 {
        self.depth
    }

    /// Get the parent function ID
    pub fn parent_func_id(&self) -> u64 {
        self.parent_func_id
    }
}

// ============================================================================
// Parsing Functions
// ============================================================================

/// Read profile data from a TCP port
/// Connects to localhost:port and reads the data
pub fn read_profile_from_port(
    port: u16,
) -> Result<(ProfileHeader, Vec<ProfileNode>, Option<SymbolMap>)> {
    let mut stream = TcpStream::connect(format!("127.0.0.1:{}", port))
        .context("Failed to connect to profiler")?;

    let mut buf = Vec::new();
    stream.read_to_end(&mut buf)?;

    parse_profile_data(&buf)
}

/// Read profile data from a binary file
/// Returns header, nodes, and optionally embedded symbol map
pub fn read_profile<P: AsRef<Path>>(
    path: P,
) -> Result<(ProfileHeader, Vec<ProfileNode>, Option<SymbolMap>)> {
    let mut file = File::open(path.as_ref()).context("Failed to open profile file")?;
    let mut buf = Vec::new();
    file.read_to_end(&mut buf)?;

    parse_profile_data(&buf)
}

/// Parse profile data from a byte buffer
pub fn parse_profile_data(
    buf: &[u8],
) -> Result<(ProfileHeader, Vec<ProfileNode>, Option<SymbolMap>)> {
    if buf.len() < 32 {
        bail!("File too small to contain header");
    }

    // Check magic
    if &buf[0..4] != MAGIC {
        bail!("Invalid magic bytes - not a valid .lprf file");
    }

    // Read header (32 bytes)
    let version = u32::from_le_bytes([buf[4], buf[5], buf[6], buf[7]]);
    let timestamp = u64::from_le_bytes([
        buf[8], buf[9], buf[10], buf[11], buf[12], buf[13], buf[14], buf[15],
    ]);
    let elapsed_ns = u64::from_le_bytes([
        buf[16], buf[17], buf[18], buf[19], buf[20], buf[21], buf[22], buf[23],
    ]);
    let node_count = u32::from_le_bytes([buf[24], buf[25], buf[26], buf[27]]);
    // bytes 28-31 are reserved padding

    let header = ProfileHeader {
        version,
        timestamp,
        elapsed_ns,
        node_count,
    };

    let mut offset = 32;

    // Read embedded symbol map
    if offset + 8 > buf.len() {
        bail!("File too small to contain symbol map counts");
    }

    let func_count = u32::from_le_bytes([
        buf[offset],
        buf[offset + 1],
        buf[offset + 2],
        buf[offset + 3],
    ]);
    offset += 4;
    let loc_count = u32::from_le_bytes([
        buf[offset],
        buf[offset + 1],
        buf[offset + 2],
        buf[offset + 3],
    ]);
    offset += 4;

    let mut symbol_map = SymbolMap::default();

    // Read functions
    for _ in 0..func_count {
        if offset + 10 > buf.len() {
            bail!("Unexpected end of file reading function entry");
        }
        let id = u64::from_le_bytes([
            buf[offset],
            buf[offset + 1],
            buf[offset + 2],
            buf[offset + 3],
            buf[offset + 4],
            buf[offset + 5],
            buf[offset + 6],
            buf[offset + 7],
        ]);
        offset += 8;
        let name_len = u16::from_le_bytes([buf[offset], buf[offset + 1]]) as usize;
        offset += 2;
        if offset + name_len > buf.len() {
            bail!("Unexpected end of file reading function name");
        }
        let name = String::from_utf8_lossy(&buf[offset..offset + name_len]).to_string();
        offset += name_len;
        symbol_map.functions.insert(id, name);
    }

    // Read locations (now includes is_user_code flag)
    for _ in 0..loc_count {
        if offset + 10 > buf.len() {
            bail!("Unexpected end of file reading location entry");
        }
        let id = u64::from_le_bytes([
            buf[offset],
            buf[offset + 1],
            buf[offset + 2],
            buf[offset + 3],
            buf[offset + 4],
            buf[offset + 5],
            buf[offset + 6],
            buf[offset + 7],
        ]);
        offset += 8;
        let file_len = u16::from_le_bytes([buf[offset], buf[offset + 1]]) as usize;
        offset += 2;
        if offset + file_len + 9 > buf.len() {
            bail!("Unexpected end of file reading location data");
        }
        let file = String::from_utf8_lossy(&buf[offset..offset + file_len]).to_string();
        offset += file_len;
        let line = u32::from_le_bytes([
            buf[offset],
            buf[offset + 1],
            buf[offset + 2],
            buf[offset + 3],
        ]);
        offset += 4;
        let col = u32::from_le_bytes([
            buf[offset],
            buf[offset + 1],
            buf[offset + 2],
            buf[offset + 3],
        ]);
        offset += 4;
        // Read is_user_code flag (u8: 0 or 1)
        let is_user = buf[offset] == 1;
        offset += 1;
        symbol_map.locations.insert(id, (file, line, col, is_user));
    }

    let embedded_map = if func_count > 0 || loc_count > 0 {
        Some(symbol_map)
    } else {
        None
    };

    // Read nodes
    let mut nodes = Vec::with_capacity(node_count as usize);
    let node_size = 49;

    for _ in 0..node_count {
        if offset + node_size > buf.len() {
            break;
        }

        let node_type = buf[offset];
        offset += 1;

        let func_id = u64::from_le_bytes([
            buf[offset],
            buf[offset + 1],
            buf[offset + 2],
            buf[offset + 3],
            buf[offset + 4],
            buf[offset + 5],
            buf[offset + 6],
            buf[offset + 7],
        ]);
        offset += 8;

        let line = u32::from_le_bytes([
            buf[offset],
            buf[offset + 1],
            buf[offset + 2],
            buf[offset + 3],
        ]);
        offset += 4;

        let column = u32::from_le_bytes([
            buf[offset],
            buf[offset + 1],
            buf[offset + 2],
            buf[offset + 3],
        ]);
        offset += 4;

        let call_count = u64::from_le_bytes([
            buf[offset],
            buf[offset + 1],
            buf[offset + 2],
            buf[offset + 3],
            buf[offset + 4],
            buf[offset + 5],
            buf[offset + 6],
            buf[offset + 7],
        ]);
        offset += 8;

        let self_time_ns = u64::from_le_bytes([
            buf[offset],
            buf[offset + 1],
            buf[offset + 2],
            buf[offset + 3],
            buf[offset + 4],
            buf[offset + 5],
            buf[offset + 6],
            buf[offset + 7],
        ]);
        offset += 8;

        let total_time_ns = u64::from_le_bytes([
            buf[offset],
            buf[offset + 1],
            buf[offset + 2],
            buf[offset + 3],
            buf[offset + 4],
            buf[offset + 5],
            buf[offset + 6],
            buf[offset + 7],
        ]);
        offset += 8;

        let depth = u16::from_le_bytes([buf[offset], buf[offset + 1]]);
        offset += 2;

        let parent_func_id = u64::from_le_bytes([
            buf[offset],
            buf[offset + 1],
            buf[offset + 2],
            buf[offset + 3],
            buf[offset + 4],
            buf[offset + 5],
            buf[offset + 6],
            buf[offset + 7],
        ]);
        offset += 8;

        nodes.push(ProfileNode {
            node_type,
            func_id,
            line,
            column,
            call_count,
            self_time_ns,
            total_time_ns,
            depth,
            parent_func_id,
        });
    }

    Ok((header, nodes, embedded_map))
}

// ============================================================================
// Helper Functions
// ============================================================================

/// Demangle a Rust symbol name
fn demangle_name(mangled: &str) -> String {
    if !mangled.starts_with("_ZN") {
        return mangled.to_string();
    }

    let mut result = Vec::new();
    let chars: Vec<char> = mangled.chars().collect();
    let mut i = 3;

    while i < chars.len() {
        let mut len_str = String::new();
        while i < chars.len() && chars[i].is_ascii_digit() {
            len_str.push(chars[i]);
            i += 1;
        }

        if len_str.is_empty() {
            break;
        }

        let len: usize = match len_str.parse() {
            Ok(l) => l,
            Err(_) => break,
        };

        if i + len <= chars.len() {
            let segment: String = chars[i..i + len].iter().collect();
            if !segment.starts_with('h') || segment.len() != 17 {
                result.push(segment);
            }
            i += len;
        } else {
            break;
        }
    }

    if result.is_empty() {
        mangled.to_string()
    } else {
        result.join("::")
    }
}

fn parse_location(s: &str) -> Option<(String, u32, u32, bool)> {
    let parts: Vec<&str> = s.rsplitn(4, ':').collect();
    if parts.len() >= 4 {
        // New format with is_user_code flag
        let is_user = parts[0] == "1";
        let col = parts[1].parse().ok()?;
        let line = parts[2].parse().ok()?;
        let file = parts[3].to_string();
        Some((file, line, col, is_user))
    } else if parts.len() >= 3 {
        // Old format without is_user_code flag (assume user code)
        let col = parts[0].parse().ok()?;
        let line = parts[1].parse().ok()?;
        let file = parts[2].to_string();
        Some((file, line, col, true))
    } else {
        None
    }
}

/// Detect if a mangled function name is from library code
fn is_mangled_library_function(name: &str) -> bool {
    // Mangled names start with _ZN
    if !name.starts_with("_ZN") {
        return false;
    }

    // Standard library: _ZN3std, _ZN4core, _ZN5alloc, etc.
    if name.starts_with("_ZN3std") || name.starts_with("_ZN4core") || name.starts_with("_ZN5alloc")
    {
        return true;
    }

    // Compiler generated: _ZN2__
    if name.starts_with("_ZN2__") {
        return true;
    }

    // Generic types containing core/std/alloc: _ZN79_$LT$core..result... or _ZN...$LT$std...
    if name.contains("$LT$core") || name.contains("$LT$std") || name.contains("$LT$alloc") {
        return true;
    }

    // Also check for core/std/alloc in the middle of the mangled name
    if name.contains("4core") || name.contains("3std") || name.contains("5alloc") {
        return true;
    }

    false
}

/// Determine if a node represents library code
fn is_node_library_code(node: &ProfileNode, symbol_map: Option<&SymbolMap>) -> bool {
    if node.is_function() {
        if node.line == 0 && node.column == 0 {
            return true;
        }
        let fname = symbol_map
            .and_then(|m| m.get_function(node.func_id))
            .unwrap_or("");
        is_mangled_library_function(fname)
    } else {
        let file_info = symbol_map.and_then(|m| m.get_location(node.func_id));
        if let Some((file, _, _, is_user)) = file_info {
            !is_user || is_mangled_library_function(file)
        } else {
            let fname = symbol_map
                .and_then(|m| m.get_function(node.func_id))
                .unwrap_or("");
            is_mangled_library_function(fname)
        }
    }
}

/// Determine if a node should be visible (not filtered as library code)
fn is_node_visible(node: &ProfileNode, symbol_map: Option<&SymbolMap>, hide_library: bool) -> bool {
    if !hide_library {
        return true;
    }

    let name = symbol_map
        .and_then(|m| m.get_function(node.func_id))
        .map(|s| s.to_string())
        .unwrap_or_default();

    if node.is_function() {
        let is_user_main = name.ends_with("::main")
            && !name.starts_with("std::")
            && !name.starts_with("core::")
            && !name.is_empty();

        if is_user_main {
            return true;
        }

        let is_library = (node.line == 0 && node.column == 0) || is_mangled_library_function(&name);
        !is_library
    } else {
        if name.starts_with("_ZN") {
            return false;
        }

        if is_mangled_library_function(&name) {
            return false;
        }

        if let Some((file, _, _, is_user)) = symbol_map.and_then(|m| m.get_location(node.func_id)) {
            if file.starts_with("_ZN") {
                return false;
            }
            return *is_user && !is_mangled_library_function(file);
        }

        true
    }
}

/// Calculate inclusive times for nodes
fn calculate_inclusive_times(
    nodes: &[ProfileNode],
    _total_elapsed_ns: u64,
    depth_offset: u16,
    symbol_map: Option<&SymbolMap>,
    hide_library: bool,
) -> HashMap<usize, u64> {
    let mut inclusive_times: HashMap<usize, u64> = HashMap::new();

    if nodes.is_empty() {
        return inclusive_times;
    }

    let visible_indices: Vec<usize> = (0..nodes.len())
        .filter(|&i| {
            nodes[i].depth >= depth_offset && is_node_visible(&nodes[i], symbol_map, hide_library)
        })
        .collect();

    if visible_indices.is_empty() {
        return inclusive_times;
    }

    for &idx in &visible_indices {
        inclusive_times.insert(idx, nodes[idx].total_time_ns);
    }

    let mut direct_children: HashMap<usize, Vec<usize>> = HashMap::new();

    for (pos, &idx) in visible_indices.iter().enumerate() {
        let my_depth = nodes[idx].depth;
        let mut children = Vec::new();
        let mut min_child_depth = u16::MAX;

        for &future_idx in visible_indices.iter().skip(pos + 1) {
            let future_depth = nodes[future_idx].depth;
            if future_depth <= my_depth {
                break;
            }
            if min_child_depth == u16::MAX {
                min_child_depth = future_depth;
            }
            if future_depth == min_child_depth {
                children.push(future_idx);
            } else if future_depth < min_child_depth {
                min_child_depth = future_depth;
                children.clear();
                children.push(future_idx);
            }
        }
        direct_children.insert(idx, children);
    }

    let mut by_depth: Vec<usize> = visible_indices.clone();
    by_depth.sort_by(|&a, &b| nodes[b].depth.cmp(&nodes[a].depth));

    for &idx in &by_depth {
        let my_time = nodes[idx].total_time_ns;
        let children = direct_children
            .get(&idx)
            .map(|v| v.as_slice())
            .unwrap_or(&[]);

        if children.is_empty() {
            continue;
        }

        let children_sum: u64 = children
            .iter()
            .map(|&c| inclusive_times.get(&c).copied().unwrap_or(0))
            .sum();

        let inclusive = my_time.max(children_sum);
        inclusive_times.insert(idx, inclusive);
    }

    inclusive_times
}

/// Calculate time adjustments for aggregating library code to callers
fn calculate_time_adjustments(
    nodes: &[ProfileNode],
    symbol_map: Option<&SymbolMap>,
    hide_library: bool,
) -> HashMap<u64, (u64, u64)> {
    let mut adjustments: HashMap<u64, (u64, u64)> = HashMap::new();

    if !hide_library {
        return adjustments;
    }

    for node in nodes {
        if is_node_library_code(node, symbol_map) {
            let (total_add, self_add) = adjustments.entry(node.parent_func_id).or_insert((0, 0));
            *total_add += node.total_time_ns;
            *self_add += node.self_time_ns;
        }
    }

    adjustments
}

/// Find the depth of the user's main function
fn find_user_main_depth(
    nodes: &[ProfileNode],
    symbol_map: Option<&SymbolMap>,
    pre_main: bool,
) -> u16 {
    if pre_main {
        return 0;
    }

    for node in nodes {
        if !node.is_function() {
            continue;
        }

        let name = symbol_map
            .and_then(|m| m.get_function(node.func_id))
            .unwrap_or("");

        if name.ends_with("::main")
            && !name.starts_with("std::")
            && !name.starts_with("core::")
            && !name.is_empty()
        {
            return node.depth;
        }
    }

    0
}

// ============================================================================
// Public API: generate_subtree
// ============================================================================

/// Generate a profile tree from raw profile data
///
/// # Arguments
/// * `header` - Profile header with metadata
/// * `nodes` - Raw profile nodes from the .lprf file
/// * `symbol_map` - Optional symbol map for name resolution
/// * `include_library` - Whether to include library code in the tree
/// * `include_pre_main` - Whether to include pre-main startup code
///
/// # Returns
/// A `ProfileTree` containing the hierarchical profile data with both
/// inclusive and exclusive times. Use `tree.get_total_time()` to get
/// the total elapsed time for percentage calculations.
pub fn generate_subtree(
    header: &ProfileHeader,
    nodes: &[ProfileNode],
    symbol_map: Option<&SymbolMap>,
    include_library: bool,
    include_pre_main: bool,
) -> ProfileTree {
    let depth_offset = find_user_main_depth(nodes, symbol_map, include_pre_main);
    let hide_library = !include_library;

    let time_adjustments = calculate_time_adjustments(nodes, symbol_map, hide_library);
    let inclusive_times = calculate_inclusive_times(
        nodes,
        header.elapsed_ns,
        depth_offset,
        symbol_map,
        hide_library,
    );

    let visible_indices: Vec<usize> = (0..nodes.len())
        .filter(|&i| {
            nodes[i].depth >= depth_offset && is_node_visible(&nodes[i], symbol_map, hide_library)
        })
        .collect();

    let mut direct_children: HashMap<usize, Vec<usize>> = HashMap::new();

    for (pos, &idx) in visible_indices.iter().enumerate() {
        let my_depth = nodes[idx].depth;
        let mut children = Vec::new();
        let mut min_child_depth = u16::MAX;

        for &future_idx in visible_indices.iter().skip(pos + 1) {
            let future_depth = nodes[future_idx].depth;
            if future_depth <= my_depth {
                break;
            }
            if min_child_depth == u16::MAX {
                min_child_depth = future_depth;
            }
            if future_depth == min_child_depth {
                children.push(future_idx);
            } else if future_depth < min_child_depth {
                min_child_depth = future_depth;
                children.clear();
                children.push(future_idx);
            }
        }
        direct_children.insert(idx, children);
    }

    let min_visible_depth = visible_indices
        .iter()
        .map(|&i| nodes[i].depth)
        .min()
        .unwrap_or(depth_offset);

    let root_indices: Vec<usize> = visible_indices
        .iter()
        .filter(|&&i| nodes[i].depth == min_visible_depth)
        .copied()
        .collect();

    fn build_tree_node(
        idx: usize,
        nodes: &[ProfileNode],
        symbol_map: Option<&SymbolMap>,
        direct_children: &HashMap<usize, Vec<usize>>,
        inclusive_times: &HashMap<usize, u64>,
        time_adjustments: &HashMap<u64, (u64, u64)>,
    ) -> TreeNode {
        let node = &nodes[idx];

        let (node_type, name, is_library) = if node.is_function() {
            let func_name = symbol_map
                .and_then(|m| m.get_function(node.func_id))
                .map(|s| s.to_string())
                .unwrap_or_else(|| format!("func_{}", node.func_id));

            let is_user_main = func_name.ends_with("::main")
                && !func_name.starts_with("std::")
                && !func_name.starts_with("core::")
                && !func_name.is_empty();
            let is_lib = !is_user_main
                && ((node.line == 0 && node.column == 0)
                    || is_mangled_library_function(&func_name));

            (TreeNodeType::Function, func_name, is_lib)
        } else {
            let file_info = symbol_map.and_then(|m| m.get_location(node.func_id));
            let (name, is_lib) = if let Some((file, _, _, is_user)) = file_info {
                let short_file = file.rsplit('/').next().unwrap_or(file);
                let is_lib =
                    !is_user || is_mangled_library_function(file) || file.starts_with("_ZN");
                (format!("{}:{}", short_file, node.line), is_lib)
            } else {
                let fname = symbol_map
                    .and_then(|m| m.get_function(node.func_id))
                    .unwrap_or("");
                let is_lib = is_mangled_library_function(fname) || fname.starts_with("_ZN");
                (format!("line {}", node.line), is_lib)
            };
            (TreeNodeType::Line, name, is_lib)
        };

        let inclusive_time_ns = inclusive_times
            .get(&idx)
            .copied()
            .unwrap_or(node.total_time_ns);
        let (_added_total, added_self) = time_adjustments
            .get(&node.func_id)
            .copied()
            .unwrap_or((0, 0));
        let exclusive_time_ns = node.self_time_ns + added_self;

        let children: Vec<TreeNode> = direct_children
            .get(&idx)
            .map(|child_indices| {
                child_indices
                    .iter()
                    .map(|&child_idx| {
                        build_tree_node(
                            child_idx,
                            nodes,
                            symbol_map,
                            direct_children,
                            inclusive_times,
                            time_adjustments,
                        )
                    })
                    .collect()
            })
            .unwrap_or_default();

        TreeNode {
            node_type,
            name,
            line: node.line,
            inclusive_time_ns,
            exclusive_time_ns,
            call_count: node.call_count,
            is_library,
            children,
        }
    }

    let roots: Vec<TreeNode> = root_indices
        .iter()
        .map(|&idx| {
            build_tree_node(
                idx,
                nodes,
                symbol_map,
                &direct_children,
                &inclusive_times,
                &time_adjustments,
            )
        })
        .collect();

    ProfileTree {
        total_time_ns: header.elapsed_ns,
        timestamp_ns: header.timestamp,
        version: header.version,
        roots,
    }
}

// ============================================================================
// Unit Tests
// ============================================================================

#[cfg(test)]
mod tests {
    use super::*;

    fn create_test_header() -> ProfileHeader {
        ProfileHeader {
            version: 1,
            timestamp: 1700000000_000_000_000,
            elapsed_ns: 1_000_000_000, // 1 second
            node_count: 0,
        }
    }

    fn create_test_node(
        is_func: bool,
        func_id: u64,
        line: u32,
        depth: u16,
        self_time: u64,
        total_time: u64,
    ) -> ProfileNode {
        ProfileNode {
            node_type: if is_func { 1 } else { 0 },
            func_id,
            line,
            column: 0,
            call_count: 1,
            self_time_ns: self_time,
            total_time_ns: total_time,
            depth,
            parent_func_id: 0,
        }
    }

    #[test]
    fn test_tree_node_percentages() {
        let node = TreeNode {
            node_type: TreeNodeType::Function,
            name: "test".to_string(),
            line: 10,
            inclusive_time_ns: 500_000_000,
            exclusive_time_ns: 100_000_000,
            call_count: 5,
            is_library: false,
            children: vec![],
        };

        let total = 1_000_000_000;
        assert!((node.inclusive_percent(total) - 50.0).abs() < 0.001);
        assert!((node.exclusive_percent(total) - 10.0).abs() < 0.001);
    }

    #[test]
    fn test_tree_node_percentages_zero_total() {
        let node = TreeNode {
            node_type: TreeNodeType::Function,
            name: "test".to_string(),
            line: 10,
            inclusive_time_ns: 500_000_000,
            exclusive_time_ns: 100_000_000,
            call_count: 5,
            is_library: false,
            children: vec![],
        };

        assert_eq!(node.inclusive_percent(0), 0.0);
        assert_eq!(node.exclusive_percent(0), 0.0);
    }

    #[test]
    fn test_profile_tree_get_total_time() {
        let tree = ProfileTree {
            total_time_ns: 5_000_000_000,
            timestamp_ns: 0,
            version: 1,
            roots: vec![],
        };

        assert_eq!(tree.get_total_time(), 5_000_000_000);
    }

    #[test]
    fn test_generate_subtree_empty_nodes() {
        let header = create_test_header();
        let nodes: Vec<ProfileNode> = vec![];
        let tree = generate_subtree(&header, &nodes, None, false, false);

        assert!(tree.roots.is_empty());
        assert_eq!(tree.get_total_time(), header.elapsed_ns);
    }

    #[test]
    fn test_generate_subtree_single_function() {
        let header = create_test_header();
        let mut symbol_map = SymbolMap::new();
        symbol_map.insert_function(1, "myapp::main".to_string());

        let nodes = vec![create_test_node(true, 1, 10, 0, 100_000, 500_000)];

        let tree = generate_subtree(&header, &nodes, Some(&symbol_map), false, true);

        assert_eq!(tree.roots.len(), 1);
        assert_eq!(tree.roots[0].name, "myapp::main");
        assert_eq!(tree.roots[0].node_type, TreeNodeType::Function);
    }

    #[test]
    fn test_generate_subtree_with_children() {
        let header = create_test_header();
        let mut symbol_map = SymbolMap::new();
        symbol_map.insert_function(1, "myapp::main".to_string());
        symbol_map.insert_location(1, "main.rs".to_string(), 20, 1, true);

        let nodes = vec![
            create_test_node(true, 1, 10, 0, 100_000, 500_000),
            create_test_node(false, 1, 20, 1, 200_000, 400_000),
        ];

        let tree = generate_subtree(&header, &nodes, Some(&symbol_map), false, true);

        assert_eq!(tree.roots.len(), 1);
        assert_eq!(tree.roots[0].children.len(), 1);
        assert_eq!(tree.roots[0].children[0].node_type, TreeNodeType::Line);
        assert!(tree.roots[0].children[0].name.contains("main.rs"));
    }

    #[test]
    fn test_demangle_name_not_mangled() {
        assert_eq!(demangle_name("hello"), "hello");
        assert_eq!(demangle_name("myapp::main"), "myapp::main");
    }

    #[test]
    fn test_demangle_name_mangled() {
        let mangled = "_ZN5myapp4main17h1234567890abcdefE";
        let demangled = demangle_name(mangled);
        assert!(demangled.contains("myapp"));
        assert!(demangled.contains("main"));
    }

    #[test]
    fn test_is_mangled_library_function() {
        assert!(is_mangled_library_function("_ZN3std2io5print"));
        assert!(is_mangled_library_function("_ZN4core3fmt"));
        assert!(is_mangled_library_function("_ZN5alloc3vec"));
        assert!(!is_mangled_library_function("_ZN5myapp4main"));
        assert!(!is_mangled_library_function("myapp::main"));
    }

    #[test]
    fn test_symbol_map_operations() {
        let mut map = SymbolMap::new();
        map.insert_function(1, "test_func".to_string());
        map.insert_location(2, "test.rs".to_string(), 10, 5, true);

        assert_eq!(map.get_function(1), Some("test_func"));
        assert_eq!(map.get_function(999), None);

        let loc = map.get_location(2);
        assert!(loc.is_some());
        let (file, line, col, is_user) = loc.unwrap();
        assert_eq!(file, "test.rs");
        assert_eq!(*line, 10);
        assert_eq!(*col, 5);
        assert!(*is_user);
    }

    #[test]
    fn test_parse_location_new_format() {
        let result = parse_location("/path/to/file.rs:42:10:1");
        assert!(result.is_some());
        let (file, line, col, is_user) = result.unwrap();
        assert_eq!(file, "/path/to/file.rs");
        assert_eq!(line, 42);
        assert_eq!(col, 10);
        assert!(is_user);
    }

    #[test]
    fn test_parse_location_old_format() {
        let result = parse_location("/path/to/file.rs:42:10");
        assert!(result.is_some());
        let (file, line, col, is_user) = result.unwrap();
        assert_eq!(file, "/path/to/file.rs");
        assert_eq!(line, 42);
        assert_eq!(col, 10);
        assert!(is_user); // defaults to user code
    }

    #[test]
    fn test_profile_header_node_count() {
        let header = ProfileHeader {
            version: 1,
            timestamp: 0,
            elapsed_ns: 1000,
            node_count: 42,
        };
        assert_eq!(header.node_count(), 42);
    }

    #[test]
    fn test_profile_node_accessors() {
        let node = ProfileNode {
            node_type: 1,
            func_id: 123,
            line: 45,
            column: 10,
            call_count: 5,
            self_time_ns: 1000,
            total_time_ns: 5000,
            depth: 2,
            parent_func_id: 100,
        };

        assert!(node.is_function());
        assert_eq!(node.func_id(), 123);
        assert_eq!(node.line(), 45);
        assert_eq!(node.column(), 10);
        assert_eq!(node.call_count(), 5);
        assert_eq!(node.self_time_ns(), 1000);
        assert_eq!(node.total_time_ns(), 5000);
        assert_eq!(node.depth(), 2);
        assert_eq!(node.parent_func_id(), 100);
    }

    #[test]
    fn test_parse_profile_data_invalid_magic() {
        let data = b"XXXX"; // Invalid magic
        let result = parse_profile_data(data);
        assert!(result.is_err());
    }

    #[test]
    fn test_parse_profile_data_too_small() {
        let data = b"LPRF"; // Only magic, no header
        let result = parse_profile_data(data);
        assert!(result.is_err());
    }

    #[test]
    fn test_parse_profile_data_valid_empty() {
        // Create minimal valid profile: header + empty symbol map
        let mut data = Vec::new();
        data.extend_from_slice(MAGIC); // 0-3: magic
        data.extend_from_slice(&1u32.to_le_bytes()); // 4-7: version
        data.extend_from_slice(&0u64.to_le_bytes()); // 8-15: timestamp
        data.extend_from_slice(&1000u64.to_le_bytes()); // 16-23: elapsed_ns
        data.extend_from_slice(&0u32.to_le_bytes()); // 24-27: node_count
        data.extend_from_slice(&0u32.to_le_bytes()); // 28-31: padding
        data.extend_from_slice(&0u32.to_le_bytes()); // func_count
        data.extend_from_slice(&0u32.to_le_bytes()); // loc_count

        let result = parse_profile_data(&data);
        assert!(result.is_ok());

        let (header, nodes, symbol_map) = result.unwrap();
        assert_eq!(header.version, 1);
        assert_eq!(header.elapsed_ns, 1000);
        assert!(nodes.is_empty());
        assert!(symbol_map.is_none());
    }

    #[test]
    fn test_library_filtering() {
        let header = create_test_header();
        let mut symbol_map = SymbolMap::new();
        symbol_map.insert_function(1, "myapp::main".to_string());
        symbol_map.insert_function(2, "_ZN3std2io5print".to_string());

        let nodes = vec![
            create_test_node(true, 1, 10, 0, 100_000, 500_000),
            create_test_node(true, 2, 0, 1, 50_000, 50_000), // library function (line=0)
        ];

        // With library code hidden
        let tree = generate_subtree(&header, &nodes, Some(&symbol_map), false, true);
        assert_eq!(tree.roots.len(), 1);
        // Library code should be filtered out - children should be empty
        assert_eq!(tree.roots[0].children.len(), 0);

        // With library code included
        let tree_with_lib = generate_subtree(&header, &nodes, Some(&symbol_map), true, true);
        assert_eq!(tree_with_lib.roots.len(), 1);
        // Library code should be visible
        assert_eq!(tree_with_lib.roots[0].children.len(), 1);
    }
}
